# Check if 129895 can be factored into a*b where a <= 510 and b <= 510
N = 129895
limit = 510
factors = []
for i in range(1, limit + 1):
    if N % i == 0:
        j = N // i
        if j <= limit:
            factors.append((i, j))
print(f"Factors (a, b) such that a<=510 and b<=510: {factors}")
